import{z as s,x as B,o as e,c as i,q as l,j as r,D as a,d as A,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"模型评估门禁","description":"","frontmatter":{"title":"模型评估门禁","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-model-eval-gates.md","filePath":"llm/pf2-model-eval-gates.md","lastUpdated":1791063341000}'),m={name:"llm/pf2-model-eval-gates.md"};function p(d,E,h,C,f,_){const t=B("Mermaid");return e(),i("div",null,[E[2]||(E[2]=l('<h1 id="模型评估门禁" tabindex="-1">模型评估门禁 <a class="header-anchor" href="#模型评估门禁" aria-label="Permalink to &quot;模型评估门禁&quot;">​</a></h1><div class="epigraph"><p>发布门禁是配方最后一次行使其权力：它决定这个模型以什么口径被记住，以及哪些对照必须陪它一起发布。</p><footer>—— 据 HELM（Liang et al., 2022）与 lm-evaluation-harness（Gao et al.）的评测规范整理</footer></div><p><a href="/llm/pf2-checkpoint-selection">上一课</a>选出交付候选；本课是它的下一关：候选模型进入发布前的全面评估门禁。与中途门禁不同，这里的判据不再答「训练怎么走」，而是答「这个模型对外是什么水平、有什么已知边界、以及这份声明是否可信」。<a href="/llm/eval-harness">评测工具链</a>与<a href="/llm/mmlu">基准的口径</a>已有专课；本课把它们组装成一次发布前的门禁流程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>发布评估的失败几乎都是口径失败。框架与模板不锁版本，两次评测的分数不可比，对外声明建立在流沙上；总分掩盖学科结构，MMLU 涨两分说不清是数学修好还是格式学会了；评测集与训练语料的污染没审计，分数里混着背过的题；基线缺失，涨跌没有参照物。这些问题在内部评测里各自都能修，但发布是一次不可撤回的对外声明——门禁的价值在于把口径问题拦在声明之前。</p><p><span class="marginnote">「污染」指评测题目或其近义改写混进了训练语料：模型靠「背过这道题」拿分，而不是靠能力。好比考卷提前泄了题——分数照样高，但说明不了任何东西。</span></p><h3 id="门禁的四关" tabindex="-1">门禁的四关 <a class="header-anchor" href="#门禁的四关" aria-label="Permalink to &quot;门禁的四关&quot;">​</a></h3><p>第一关，<strong>口径锁定</strong>：评测框架版本、任务配置、适配器与聊天模板全部钉死并写进报告；多选与生成式分表，不混成单一「开源评测分」。第二关，<strong>能力分层</strong>：知识、数学、代码、多语言、长上下文分层报告，保留学科细分；总分只作索引，见 <a href="/llm/mmlu">MMLU 的口径</a>。第三关，<strong>污染审计</strong>：发布前完成对评测集的训练语料检索审计，报告命中口径与处理方式，见<a href="/llm/eval-contamination">评测污染</a>。第四关，<strong>对照与边界</strong>：同代基线在<strong>同口径</strong>下重跑（不是抄榜单）；安全评测与拒答行为单独成表；饱和基准按<a href="/llm/benchmark-saturation">饱和口径</a>降权或换仪器。</p>',8)),(e(),r(o,null,{default:a(()=>[n(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAND%5B%22%E5%80%99%E9%80%89%E6%A8%A1%E5%9E%8B%EF%BC%88%E5%B8%A6%E8%B0%B1%E7%B3%BB%EF%BC%89%22%5D%20--%3E%20G1%7B%22%E5%8F%A3%E5%BE%84%E9%94%81%E5%AE%9A%EF%BC%9A%E6%A1%86%E6%9E%B6%20%2F%20%E6%A8%A1%E6%9D%BF%20%2F%20%E7%89%88%E6%9C%AC%22%7D%0A%20%20G1%20--%3E%20G2%5B%22%E8%83%BD%E5%8A%9B%E5%88%86%E5%B1%82%E6%8A%A5%E5%91%8A%22%5D%0A%20%20G2%20--%3E%20G3%7B%22%E6%B1%A1%E6%9F%93%E5%AE%A1%E8%AE%A1%E9%80%9A%E8%BF%87%EF%BC%9F%22%7D%0A%20%20G3%20--%3E%7C%E5%91%BD%E4%B8%AD%E8%B6%85%E6%A0%87%7C%20FIX%5B%22%E5%89%AA%E8%B7%A8%E5%BA%A6%E6%88%96%E5%A3%B0%E6%98%8E%E5%8F%A3%E5%BE%84%22%5D%0A%20%20G3%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20G4%5B%22%E5%90%8C%E5%8F%A3%E5%BE%84%E5%9F%BA%E7%BA%BF%E5%AF%B9%E7%85%A7%20%2B%20%E5%AE%89%E5%85%A8%E8%A1%A8%22%5D%0A%20%20FIX%20--%3E%20G4%0A%20%20G4%20--%3E%20REL%5B%22%E5%8F%91%E5%B8%83%EF%BC%9A%E5%88%86%E6%95%B0%20%2B%20%E8%BE%B9%E7%95%8C%20%2B%20%E9%85%8D%E6%96%B9%E6%8C%87%E9%92%88%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行三条。第一，<strong>基线同口径重跑</strong>：对照模型在本方 harness 上重测，逐题输出保留，使差异可下钻到题目层；抄别人报告的数字做对照是最常见的不可比来源。第二，<strong>门禁判据预注册</strong>：哪些层必须过线、哪些允许带边界发布，在评测前写明；「高分就发、低分再议」不是门禁。第三，<strong>报告三件套</strong>：分数表、已知失败模式清单、指向训练配方的指针——评测分数离开配方口径就没有复述价值，这是<a href="/llm/ti-recipe-management">配方管理</a>的收尾动作。</p><p><span class="marginnote">逐题输出是门禁最便宜的保险：分数异常时能下钻到题目层定位是抽取器、模板还是能力问题；只留总分 CSV 的团队，每次异常都要重新跑一遍全量评测。</span></p><p><span class="marginnote">直觉类比：两支队伍用不同卷子考出的分数没法直接排名；让基线模型在你自己的考卷（框架、模板、抽取器）上重考一遍，才是同一把尺子量出来的差距。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么基线必须同口径重跑：基准分数绑定框架实现、few-shot 排布、模板与抽取器，任何一个都会在实现间摆动几个点；跨报告对比把口径差读成能力差，是排行榜时代最系统的噪声源。为什么污染审计是硬关：污染把「能力」偷换成「记忆」，且补考无法补救——训练完成后发现的泄漏只能声明口径，不能消除；这是配方权力最后一次能真正改变结果的地方。为什么安全单独成表：能力总分不携带拒答与越权信息，安全是另一根轴，混进总分会让两根轴互相稀释，见对齐评测各课的口径。</p><p><span class="marginnote">常见误区：初学者容易以为安全是能力的一部分，可以折进总分。实际上安全（拒答、越权）与能力是两根独立的轴，混在一起只会互相稀释——能力榜高不代表更安全，反之亦然。</span></p>',7)),(e(),r(o,null,{default:a(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E6%A8%A1%E5%9E%8B%EF%BC%8C%E5%90%8C%E4%B8%80%E5%A5%97%E9%A2%98%22%5D%20--%3E%20A%5B%22%E6%A1%86%E6%9E%B6%E5%AE%9E%E7%8E%B0%E4%B8%8D%E5%90%8C%22%5D%0A%20%20M%20--%3E%20B%5B%22few-shot%20%E6%8E%92%E5%B8%83%E4%B8%8D%E5%90%8C%22%5D%0A%20%20M%20--%3E%20C%5B%22%E8%81%8A%E5%A4%A9%E6%A8%A1%E6%9D%BF%E4%B8%8D%E5%90%8C%22%5D%0A%20%20M%20--%3E%20D%5B%22%E7%AD%94%E6%A1%88%E6%8A%BD%E5%8F%96%E5%99%A8%E4%B8%8D%E5%90%8C%22%5D%0A%20%20A%20--%3E%20E%5B%22%E5%90%84%E8%87%AA%E6%91%86%E5%8A%A8%E9%9B%B6%E7%82%B9%E5%87%A0%E5%88%B0%E5%87%A0%E4%B8%AA%E7%82%B9%22%5D%0A%20%20B%20--%3E%20E%0A%20%20C%20--%3E%20E%0A%20%20D%20--%3E%20E%0A%20%20E%20--%3E%20F%7B%22%E8%B7%A8%E6%8A%A5%E5%91%8A%E7%9B%B4%E6%8E%A5%E6%AF%94%E5%88%86%E6%95%B0%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%E6%98%AF%7C%20G%5B%22%E5%8F%A3%E5%BE%84%E5%B7%AE%E8%A2%AB%E8%AF%BB%E6%88%90%E8%83%BD%E5%8A%9B%E5%B7%AE%22%5D%0A%20%20F%20--%3E%7C%E5%90%A6%EF%BC%8C%E5%90%8C%E5%8F%A3%E5%BE%84%E9%87%8D%E8%B7%91%7C%20H%5B%22%E5%AF%B9%E7%85%A7%E5%8F%AF%E4%BF%A1%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=l('<p>这张图回答的是「为什么同一模型在不同报告里能差出几个点」：四个口径部件各自引入摆动，叠加后足以吞掉真实的能力差距——所以基线要同口径重跑。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课是发布前的能力与口径门禁，不含对齐专项评测的深钻——红队、越权与诚实性的方法论在对齐评测课程里，本课只要求其结论入表。基准怎么选、饱和怎么判是<a href="/llm/benchmark-saturation">基准演进</a>与<a href="/llm/live-benchmarks">动态基准</a>的课题。评测与训练的隔离（探针集、去污管线）在中途门禁一课已定，这里只消费其产物。对外声明的措辞规范——哪些结论有背书、哪些是外推——属于<a href="/llm/eco-repro-report-writing">开源发布</a>的写作课，本课交付的是它引用的数字与边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发布门禁四关：口径锁定、能力分层、污染审计、同口径对照加安全表。</li><li>基线在本方 harness 重跑，逐题输出保留；抄榜做对照不可比。</li><li>判据预注册：哪些层过线、哪些带边界发布，评测前写明。</li><li>报告三件套：分数表、已知失败模式、配方指针；分数离开配方口径不可复述。</li><li>出处：Gao et al., lm-evaluation-harness；Liang et al., HELM, 2022；Hendrycks et al., MMLU, ICLR 2021。</li></ul>',5))])}const F=s(m,[["render",p]]);export{D as __pageData,F as default};
